UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/CostaBrava.unity", UnityEditor.SceneManagement.OpenSceneMode.Single);
var garage = UnityEngine.Object.FindObjectOfType<VehicleGarage>();
if (garage == null) return "no garage";
var sb = new System.Text.StringBuilder();
for (int i = 0; i < garage.variants.Length; i++)
{
    if (garage.specIds[i] != "hdSportsCar") continue;
    garage.Apply(i);
    var v = garage.variants[i];
    sb.AppendLine("variant root=" + v.root.name + " active=" + v.root.activeSelf);
    foreach (Transform t in v.root.GetComponentsInChildren<Transform>())
    {
        if (t.GetComponent<Renderer>() == null) continue;
        var b = t.GetComponent<Renderer>().localBounds;
        Vector3 carLocal = garage.transform.InverseTransformPoint(t.GetComponent<Renderer>().transform.TransformPoint(b.center));
        Vector3 scale = t.GetComponent<Renderer>().transform.lossyScale;
        sb.AppendLine("  " + t.name + " localRot=" + t.localRotation.eulerAngles + " center=" + carLocal.ToString("F2") + " ext=" + new Vector3(b.extents.x*scale.x, b.extents.y*scale.y, b.extents.z*scale.z).ToString("F2"));
    }
    break;
}
Debug.Log("PROBE9 " + sb.ToString().Replace("\r", "").Replace("\n", " || "));
return sb.ToString();
